(() => {
  function openTabSearch(prefill = "") {
    if (!window.gURLBar) return;

    gURLBar.focus();

    // Put the token that activates "Search tabs" into the urlbar
    const v = "% " + prefill;
    gURLBar.value = v;

    // Move caret to end
    try { gURLBar.setSelectionRange(v.length, v.length); } catch {}

    // Trigger an input so the urlbar rebuilds results
    const field = gURLBar.inputField || gURLBar.textbox?.inputField;
    if (field) field.dispatchEvent(new Event("input", { bubbles: true }));

    // Open the view (suggestions) explicitly if available
    try { gURLBar.openView(); } catch {}
  }

  // Example: open tab search immediately on startup
  const start = () => openTabSearch("");

  if (gBrowserInit?.delayedStartupFinished) {
    start();
  } else {
    Services.obs.addObserver(function obs(subject, topic) {
      if (topic === "browser-delayed-startup-finished" && subject === window) {
        Services.obs.removeObserver(obs, topic);
        start();
      }
    }, "browser-delayed-startup-finished");
  }
})();
